//! A factory contract that creates the contracts of a dapp.
//!
//! Anyone may call `new_contract` of a contract generated by `#[odra::module(factory = on)]`. The holder
//! of the factory access, the account that deployed the factory, may change that:
//! - `set_factory_creator` lets only the given address create children, e.g. the contract that keeps
//!   track of them;
//! - `set_factory_dapp_registry` points the factory to a dapp registry: the factory belongs to that
//!   dapp, and so does every child it creates from then on. A factory gets a registry only after a
//!   creator: otherwise anyone could add contracts to the dapp.
//!
//! A child the factory creates points to the factory's registry and is added to it. The registry
//! verifies the child and accepts it from a registrar only, so register the factory as a registrar
//! right after pointing it to the registry: until then `new_contract` reverts. A child created before
//! the factory had a registry points to it after `upgrade_child_contract`; the registry owner adds it.
//! A child keeps the registry it points to: on Casper an upgrade cannot replace a named key the child
//! already has, so pointing the factory to another registry moves only the children created afterwards.
//!
//! The factory and its children answer `get_dapp_registry`, which a dapp registry calls to verify a
//! contract points back to it: the children run the factory's wasm, which exports the entry point, so
//! the child module needs no code of its own and cannot have its own `get_dapp_registry`.
//!
//! The creator lives under the [`CREATOR_KEY`] named key and the registry under the [`REGISTRY_KEY`]
//! item of the [`DAPP_KEY`] dictionary, the item the `DappContractBase` module of `odra-modules` uses, so
//! both can be read from the chain. A child gets its own [`DAPP_KEY`] dictionary with the registry from
//! the factory. OdraVM runs the entry points natively through `odra::host::factory`, with the same
//! rules.
use crate::prelude::*;
use crate::{CallDef, ContractEnv, ExecutionEnv};
use casper_event_standard::EventInstance;
use casper_types::bytesrepr::ToBytes;
use casper_types::RuntimeArgs;

/// The named key of the dictionary holding a contract's dapp data.
pub const DAPP_KEY: &str = "__dapp";
/// The item of the [`DAPP_KEY`] dictionary holding the dapp registry a contract belongs to.
pub const REGISTRY_KEY: &str = "registry";
/// The named key of the only address allowed to create the factory's children.
pub const CREATOR_KEY: &str = "__factory_creator";
/// The entry point returning the dapp registry of the factory or of its child, the same as in the
/// `DappContract` interface.
pub const GET_DAPP_REGISTRY: &str = "get_dapp_registry";
/// The entry point setting the factory's dapp registry; only the factory access holder may call it.
pub const SET_DAPP_REGISTRY: &str = "set_factory_dapp_registry";
/// The argument of [`SET_DAPP_REGISTRY`].
pub const REGISTRY_ARG: &str = "registry";
/// The entry point setting the factory's creator; only the factory access holder may call it.
pub const SET_CREATOR: &str = "set_factory_creator";
/// The argument of [`SET_CREATOR`].
pub const CREATOR_ARG: &str = "creator";
/// The entry point of a dapp registry the factory calls to add a child.
pub const ADD_DAPP_CONTRACT: &str = "add_dapp_contract";
/// The arguments of [`ADD_DAPP_CONTRACT`].
pub const DAPP_CONTRACT_ARG: &str = "dapp_contract";
/// See [`DAPP_CONTRACT_ARG`].
pub const IS_REGISTRAR_ARG: &str = "is_registrar";

/// Returns the dapp registry the factory adds its children to, if any.
pub fn dapp_registry(env: &ContractEnv) -> Option<Address> {
    // A factory without a creator has no registry; checking first keeps the dictionary, which a read
    // creates in wasm, out of factories that are not part of a dapp.
    creator(env)?;
    env.get_dictionary_value(DAPP_KEY, REGISTRY_KEY.as_bytes())
}

/// Returns the dapp registry of the contract being executed, a factory or one of its children, if any.
///
/// In wasm the read creates the [`DAPP_KEY`] dictionary of a contract without one; the entry point
/// reverts then, which rolls it back.
pub fn contract_dapp_registry(env: &ContractEnv) -> Option<Address> {
    env.get_dictionary_value(DAPP_KEY, REGISTRY_KEY.as_bytes())
}

/// Returns the only address allowed to create the factory's children, if any.
pub fn creator(env: &ContractEnv) -> Option<Address> {
    env.get_named_value(CREATOR_KEY)
}

/// Stores the factory's dapp registry and returns the previous one.
///
/// Reverts with [`ExecutionError::DappRegistryNotAContract`] if `registry` is not a contract and with
/// [`ExecutionError::FactoryCreatorNotSet`] if the factory has no creator.
pub fn set_dapp_registry(env: &ContractEnv, registry: Address) -> Option<Address> {
    if !registry.is_contract() {
        env.revert(ExecutionError::DappRegistryNotAContract);
    }
    if creator(env).is_none() {
        env.revert(ExecutionError::FactoryCreatorNotSet);
    }
    let previous = contract_dapp_registry(env);
    env.set_dictionary_value(DAPP_KEY, REGISTRY_KEY.as_bytes(), registry);
    previous
}

/// Stores the factory's creator and returns the previous one.
pub fn set_creator(env: &ContractEnv, creator_address: Address) -> Option<Address> {
    let previous = creator(env);
    env.set_named_value(CREATOR_KEY, creator_address);
    previous
}

/// Reverts with [`ExecutionError::CallerNotFactoryCreator`] if the factory has a creator and the
/// caller is someone else.
///
/// In wasm, call it before the caller of the factory is overridden for the child.
pub fn assert_creator(env: &ContractEnv) {
    if let Some(creator) = creator(env) {
        if env.caller() != creator {
            env.revert(ExecutionError::CallerNotFactoryCreator);
        }
    }
}

/// Adds the child to the factory's dapp registry, if the factory has one.
pub fn register_child(env: &ContractEnv, child: Address) {
    if let Some(registry) = dapp_registry(env) {
        let mut args = RuntimeArgs::new();
        let _ = args.insert(DAPP_CONTRACT_ARG, child);
        let _ = args.insert(IS_REGISTRAR_ARG, false);
        env.call_contract::<()>(
            registry,
            CallDef::new(String::from(ADD_DAPP_CONTRACT), true, args)
        );
    }
}

/// The `set_factory_creator` entry point, wasm and OdraVM alike: stores the creator named by the
/// [`CREATOR_ARG`] argument and emits the event `event` builds from the previous and the new creator.
/// The caller must hold the factory access, which the entry point's group checks in wasm.
pub fn run_set_creator<E: ToBytes + EventInstance>(
    env: &ContractEnv,
    event: fn(Option<Address>, Address) -> E
) {
    let creator: Address = execution_env(env).get_named_arg(CREATOR_ARG);
    let previous = set_creator(env, creator);
    env.emit_event(event(previous, creator));
}

/// The `set_factory_dapp_registry` entry point, wasm and OdraVM alike: stores the registry named by
/// the [`REGISTRY_ARG`] argument and emits the event `event` builds from the previous and the new
/// registry. The caller must hold the factory access, which the entry point's group checks in wasm.
pub fn run_set_dapp_registry<E: ToBytes + EventInstance>(
    env: &ContractEnv,
    event: fn(Option<Address>, Address) -> E
) {
    let registry: Address = execution_env(env).get_named_arg(REGISTRY_ARG);
    let previous = set_dapp_registry(env, registry);
    env.emit_event(event(previous, registry));
}

/// Reads the named arguments of the call the way a generated entry point does: a missing or
/// malformed one reverts.
fn execution_env(env: &ContractEnv) -> ExecutionEnv {
    ExecutionEnv::new(Rc::new(env.clone()))
}
